        bodyKo: "The 와일드 원 스켈레톤 X-Lite features a revolutionary ultra-light case construction that pushes the 와일드 원 concept to new extremes, beyond the limits of lightness for a watch of its size, functionality and robustness. Its complex, layered architecture is composed of more than 30 individual components, assembled like building blocks for maximum structural integrity. 케이지는 블랙 NORTEQ로 제작되며, 효율적인 충격 흡수 시스템을 갖추고 있습니다. 핵심에는 NORTEQ·티타늄·알루미늄 케이스 안에 독자적인 X-Lite 케이싱 링이 자리합니다. 케이스 곳곳에 충격 흡수 장치가 전략적으로 배치되어, 슬림하고 착용하기 좋은 프로필을 유지하면서도 5,000G 이상의 충격을 견딜 수 있습니다.",
