        titleKo: "NORTEQ® CASE & REVOLUTIONARY CASE CONSTRUCTION",
        bodyKo: "NORTEQ® is an ultra-light, ultra-robust material that was created exclusively for NORQAIN and its watches and is the result of a close collaboration between NORQAIN, Jean-Claude Biver and BIWI SA. This high-performance material has a striking marble effect. The NORTEQ® carbon fibre composite offers the perfect balance between density, elasticity and resistance for optimised shock-absorption. The case has separate top and bottom NORTEQ® parts which serve as a protective cage and are connected and secured with custom-made screws. The BIWI rubber bumper reliably absorbs shocks during even the most extreme activities. In total, the case is made of 25 parts, including four screws which are engraved with a mountain-peak design.",
